description:
Read a `FILE *` line by line, with lines of any length, and report on it:

```c
struct line_stats { size_t lines; size_t longest_len; char *longest; size_t blank; };
int line_stats(FILE *f, struct line_stats *out);    /* 0, or -1 if out of memory; out->longest is a copy the caller frees */
```

- a line ends at `\n`; a `\r` just before it is not part of the line; the last line may have no `\n`;
- `blank` counts lines that are empty or only spaces and tabs;
- `longest` is a copy of the first longest line (an empty string when there are no lines, never `NULL` on success).

Do not assume any maximum line length: grow your buffer with `realloc`.

starter.solution.c:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct line_stats { size_t lines; size_t longest_len; char *longest; size_t blank; };

int line_stats(FILE *f, struct line_stats *out)
{
    char buf[100];
    out->lines = 0;
    out->longest_len = 0;
    out->longest = NULL;
    out->blank = 0;
    while (fgets(buf, sizeof buf, f)) out->lines++;
    return 0;
}

solution.solution.c:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct line_stats { size_t lines; size_t longest_len; char *longest; size_t blank; };

static char *read_line(FILE *f, size_t *len_out, int *oom)
{
    size_t cap = 64, len = 0;
    char *buf = malloc(cap);
    if (!buf) { *oom = 1; return NULL; }
    int c;
    while ((c = fgetc(f)) != EOF && c != '\n') {
        if (len + 1 >= cap) {
            char *p = realloc(buf, cap * 2);
            if (!p) { free(buf); *oom = 1; return NULL; }
            buf = p;
            cap *= 2;
        }
        buf[len++] = (char)c;
    }
    if (c == EOF && len == 0) { free(buf); return NULL; }
    if (len > 0 && buf[len - 1] == '\r') len--;
    buf[len] = '\0';
    *len_out = len;
    return buf;
}

int line_stats(FILE *f, struct line_stats *out)
{
    out->lines = 0;
    out->longest_len = 0;
    out->blank = 0;
    out->longest = NULL;
    int oom = 0;
    size_t len;
    char *line;
    while ((line = read_line(f, &len, &oom)) != NULL) {
        out->lines++;
        if (strspn(line, " \t") == len) out->blank++;
        if (!out->longest || len > out->longest_len) {
            free(out->longest);
            out->longest = line;
            out->longest_len = len;
        } else {
            free(line);
        }
    }
    if (oom) {
        free(out->longest);
        out->longest = NULL;
        return -1;
    }
    if (!out->longest) {
        out->longest = calloc(1, 1);
        if (!out->longest) return -1;
    }
    return 0;
}

unitTests:
TEST("counts lines and blanks") { FILE *f = tmpfile(); fputs("one


four
", f); rewind(f); struct line_stats s; CHECK_EQ(line_stats(f, &s), 0); CHECK_EQ((int)s.lines, 4); CHECK_EQ((int)s.blank, 2); CHECK_STR(s.longest, "four"); free(s.longest); fclose(f); }
TEST("a very long line and no final newline") { FILE *f = tmpfile(); fputs("short
", f); for (int i = 0; i < 5000; i++) fputc('x', f); rewind(f); struct line_stats s; CHECK_EQ(line_stats(f, &s), 0); CHECK_EQ((int)s.lines, 2); CHECK_EQ((int)s.longest_len, 5000); CHECK_EQ((int)strlen(s.longest), 5000); free(s.longest); fclose(f); }
TEST("windows line endings and the first longest") { FILE *f = tmpfile(); fputs("abc
xyz
ab
", f); rewind(f); struct line_stats s; line_stats(f, &s); CHECK_EQ((int)s.lines, 3); CHECK_STR(s.longest, "abc"); CHECK_EQ((int)s.longest_len, 3); free(s.longest); fclose(f); }
TEST("an empty file") { FILE *f = tmpfile(); struct line_stats s; CHECK_EQ(line_stats(f, &s), 0); CHECK_EQ((int)s.lines, 0); CHECK(s.longest != NULL); CHECK_STR(s.longest, ""); free(s.longest); fclose(f); }

